/// <summary>
/// It is helper class contains to create the Accrual journal
/// </summary>
final class METDutyRollVarianceAccuralJournalPostingHelper
{
}

Method.Source:
/// <summary>
/// Creates the Accrual journal for duty roll variance
/// </summary>
/// <param name = "_metExciseDutyParameteres"> METExciseDutyParameteres </param>
/// <param name = "_metDutyRollVariance"> METDutyRollVariance </param>
/// <param name = "_metInventTransExciseRegisterUpdateView"> METInventTransExciseRegisterUpdateView </param>
/// <param name = "_accrualPostingAmt"> METVendorClaimAmount </param>
public static void createAccuralJournal(METExciseDutyParameteres _metExciseDutyParameteres, METDutyRollVariance _metDutyRollVariance, METInventTransExciseRegisterUpdateView _metInventTransExciseRegisterUpdateView, METVendorClaimAmount _accrualPostingAmt)
{
    LedgerJournalTable                  ledgerJournalTable;
    LedgerJournalTrans                  ledgerJournalTrans;
    LedgerJournalCheckPost              journalCheckPost;
    LedgerJournalName                   ledgerJournalName;
    NumberSeq                           numberseq;
    Voucher                             voucher;
    TaxItemGroupHeading                 taxItemGroupHeading;
    DimensionAttributeValueCombination  dimensionAttributeValueCombination;
    InventSiteLinkedDimensionValueSet   defaultDimension = PurchLine::findInventTransId(_metInventTransExciseRegisterUpdateView.InventTransId).DefaultDimension;

    select firstonly CurrencyCode, JournalName, NumberSequenceTable from ledgerJournalName
        where ledgerJournalName.JournalName == _metExciseDutyParameteres.JournalName;

    ledgerJournalTable.company(curExt());
    ledgerJournalTable.JournalName                  = ledgerJournalName.JournalName;
    ledgerJournalTable.initFromLedgerJournalName();
    ledgerJournalTable.NumberSequenceTable          = ledgerJournalName.NumberSequenceTable;
    ledgerJournalTable.METExciseRegisterReferenceId = _metDutyRollVariance.ExciseRegisterReferenceId;
    ledgerJournalTable.DefaultDimension             = defaultDimension;
    ledgerJournalTable.insert();

    if (ledgerJournalTable.RecId)
    {
        ledgerJournalTrans = METDutyRollVarianceAccuralJournalPostingHelper::mapLedgerJournalTrans(ledgerJournalTrans, ledgerJournalTable, ledgerJournalName, _metDutyRollVariance, _metExciseDutyParameteres, _accrualPostingAmt, defaultDimension);
        ledgerJournalTrans.insert();

        if (ledgerJournalTrans.RecId)
        {
            journalCheckPost = LedgerJournalCheckPost::newLedgerJournalTable(ledgerJournalTable, NoYes::Yes);
            journalCheckPost.runOperation();
        }

        ledgerJournalTable.reread();

        if (ledgerJournalTable.Posted)
        {
            info(strFmt("@MET:AccrualJournalPostMsg", _metDutyRollVariance.Lodgement, _metDutyRollVariance.ItemId, _metDutyRollVariance.PurchId, 
                ledgerJournalTable.JournalNum));

            if (_metDutyRollVariance.RecId != 0)
            {
                ttsbegin;
                _metDutyRollVariance.selectForUpdate(true);
                _metDutyRollVariance.IsAccrualPosted = NoYes::Yes;
                _metDutyRollVariance.update();
                ttscommit;
            }
            else    
                _metDutyRollVariance.IsAccrualPosted = NoYes::Yes;
        }
    }
}

/// <summary>
/// Maps the data to ledger journal trans table
/// </summary>
/// <param name = "_ledgerJournalTrans"> LedgerJournalTrans </param>
/// <param name = "_ledgerJournalTable"> LedgerJournalTable </param>
/// <param name = "_ledgerJournalName"> LedgerJournalName </param>
/// <param name = "_metDutyRollVariance"> METDutyRollVariance </param>
/// <param name = "_metExciseDutyParameteres"> METExciseDutyParameteres </param>
/// <param name = "_accrualPostingAmt"> METVendorClaimAmount </param>
/// <param name = "_defaultDimension"> InventSiteLinkedDimensionValueSet </param>
/// <returns> LedgerJournalTrans </returns>
public static LedgerJournalTrans mapLedgerJournalTrans(LedgerJournalTrans _ledgerJournalTrans, LedgerJournalTable _ledgerJournalTable,
    LedgerJournalName _ledgerJournalName, METDutyRollVariance _metDutyRollVariance, METExciseDutyParameteres _metExciseDutyParameteres, 
    METVendorClaimAmount _accrualPostingAmt, InventSiteLinkedDimensionValueSet _defaultDimension)
{
    MainAccount mainAccount;
    Voucher     voucher = new JournalVoucherNum(JournalTableData::newTable(_ledgerJournalTable)).getNew(false);

    _ledgerJournalTrans.Company                 = curExt();
    _ledgerJournalTrans.JournalNum              = _ledgerJournalTable.JournalNum;
    _ledgerJournalTrans.TransDate               = today();
    _ledgerJournalTrans.LineNum                 = LedgerJournalTrans::lastLineNum(_ledgerJournalTrans.JournalNum);
    _ledgerJournalTrans.Voucher                 = voucher;
    _ledgerJournalTrans.CurrencyCode            = _ledgerJournalName.CurrencyCode;
    _ledgerJournalTrans.ExchRate                = _ledgerJournalTable.ExchRate;
    mainAccount                                 = MainAccount::findByMainAccountId(_metExciseDutyParameteres.AccuralAccountNum);
    _ledgerJournalTrans.AccountType             = LedgerJournalACType::Ledger;
    _ledgerJournalTrans.LedgerDimension         = METDutyRollVarianceAccuralJournalPostingHelper::combineMainAccoutAndDefaultDimension(mainAccount.MainAccountId,
        _defaultDimension);
    mainAccount                                 = MainAccount::findByMainAccountId(_metExciseDutyParameteres.DutyVarianceAccountNum);
    _ledgerJournalTrans.OffsetAccountType       = LedgerJournalACType::Ledger;
    _ledgerJournalTrans.OffsetLedgerDimension   =  METDutyRollVarianceAccuralJournalPostingHelper::combineMainAccoutAndDefaultDimension(mainAccount.MainAccountId,
        _defaultDimension);
    _accrualPostingAmt                          = decRound(_accrualPostingAmt, 2);

    if (_accrualPostingAmt > 0)
        _ledgerJournalTrans.AmountCurCredit     = _accrualPostingAmt;
    else
        _ledgerJournalTrans.AmountCurDebit      = abs(_accrualPostingAmt);

    _ledgerJournalTrans.TaxItemGroup            = _metExciseDutyParameteres.TaxItemGroup;
    _ledgerJournalTrans.TaxGroup                = VendTable::find(_metDutyRollVariance.VendAccount).TaxGroup;

    return _ledgerJournalTrans;
}

/// <summary>
/// Gets the Ledger dimension based on the main account and default dimension 
/// </summary>
/// <param name = "_ledgerJournalAC"> LedgerJournalAC </param>
/// <param name = "_defaultDimension"> DimensionDefault </param>
/// <returns> DimensionDynamicAccount </returns>
public static DimensionDynamicAccount combineMainAccoutAndDefaultDimension(LedgerJournalAC _ledgerJournalAC, DimensionDefault _defaultDimension)
{
    container                           conDimName;
    DimensionValue                      dimValue;
    Name                                dimName;
    int                                 iterator = 1;
    DimensionAttributeValueContract     valueContract;
    DimensionAttributeValueCombination  dimensionAttributeValueCombination;
    DimensionStorage                    dimStorage;
    LedgerAccountContract               ledgerAccountContract = new LedgerAccountContract();
    List                                listValueContract = new List(Types::Class);

    conDimName = METDutyRollVarianceAccuralJournalPostingHelper::getDimensionAttriuteName();
    while (iterator <= conLen(conDimName) )
    {
        dimName = conPeek(conDimName, iterator);
        dimValue = METDutyRollVarianceAccuralJournalPostingHelper::getDimensionAttributeValue(_defaultDimension, dimName);
        if(dimValue)
        {
            valueContract = new DimensionAttributeValueContract();
            valueContract.parmName(dimName);
            valueContract.parmValue(dimValue);
            listValueContract.addEnd(valueContract);
        }
        iterator ++;
    }
    ledgerAccountContract.parmMainAccount(_ledgerJournalAC);
    ledgerAccountContract.parmValues(listValueContract);
    dimStorage = DimensionServiceProvider::buildDimensionStorageForLedgerAccount(ledgerAccountContract);
    dimensionAttributeValueCombination = DimensionAttributeValueCombination::find(dimStorage.save());
    return dimensionAttributeValueCombination.RecId;
}

/// <summary>
/// Gets the display value for the attribute based on the default dimension
/// </summary>
/// <param name = "_defaultDimension"> RecId </param>
/// <param name = "_dimName"> Name </param>
/// <returns> It returns the dimension attribute value for given default dimension </returns>
public static Description255 getDimensionAttributeValue(RecId _defaultDimension, Name _dimName)
{
    DimensionAttributeValueSetStorage  dimStorage;
    dimStorage = DimensionAttributeValueSetStorage::find(_defaultDimension);
    return dimStorage.getDisplayValueByDimensionAttribute(DimensionAttribute::findByName(_dimName).RecId);
}

/// <summary>
/// Gets the dimension attribute name
/// </summary>
/// <returns> container </returns>
public static container getDimensionAttriuteName()
{
    DimensionAttribute         dimAttr;
    DimensionAttributeSetItem  dimAttrSetItem;
    DimensionEnumeration       dimensionSetId;
    container                  dimensionName;

    dimensionSetId = DimensionCache::getDimensionAttributeSetForLedger();

    while select dimAttr order by Name
        where dimAttr.Type != DimensionAttributeType::MainAccount
       join RecId from dimAttrsetItem
        where dimAttrSetItem.DimensionAttribute == dimAttr.RecId &&
        dimAttrSetItem.DimensionAttributeSet == dimensionSetId
    {
        dimensionName += dimAttr.Name;
    }
    return DimensionName;
}
